const card=JSON.parse(document.querySelector('#card-data').textContent),score=document.querySelector('#score'),decision=document.querySelector('#decision');for(const input of document.querySelectorAll('input[type=range]'))input.addEventListener('input',()=>input.closest('.criterion').querySelector('output').value=input.value);function calculate(){let total=0;for(const criterion of card.criteria){const input=document.querySelector('[data-id="'+criterion.id+'"]');total+=Number(input.value)*criterion.weight}const value=Math.round(total/100);score.textContent=value;decision.textContent=value>=75?'READY':value>=50?'CONDITIONAL':'HOLD'}document.querySelector('#calculate').addEventListener('click',calculate);calculate();
